<template><el-container class="merchant-layout"><el-aside width="220px"><div class="logo"><h3>TLLOS 商家后台</h3></div><el-menu :default-active="$route.path" router background-color="#001529" text-color="#fff" active-text-color="#409eff"><el-menu-item index="/dashboard"><el-icon><Odometer/></el-icon><span>工作台</span></el-menu-item><el-sub-menu index="product"><template #title><el-icon><Goods/></el-icon><span>商品管理</span></template><el-menu-item index="/product/list">商品列表</el-menu-item><el-menu-item index="/product/category">商品分类</el-menu-item></el-sub-menu><el-sub-menu index="order"><template #title><el-icon><Document/></el-icon><span>订单管理</span></template><el-menu-item index="/order/list">订单列表</el-menu-item></el-sub-menu><el-sub-menu index="marketing"><template #title><el-icon><Present/></el-icon><span>营销管理</span></template><el-menu-item index="/marketing/coupon">优惠券</el-menu-item><el-menu-item index="/marketing/seckill">秒杀活动</el-menu-item></el-sub-menu><el-sub-menu index="finance"><template #title><el-icon><Money/></el-icon><span>财务管理</span></template><el-menu-item index="/finance/list">财务明细</el-menu-item><el-menu-item index="/finance/settlement">结算管理</el-menu-item></el-sub-menu><el-menu-item index="/data/overview"><el-icon><DataAnalysis/></el-icon><span>数据概览</span></el-menu-item><el-menu-item index="/shop/info"><el-icon><Setting/></el-icon><span>店铺设置</span></el-menu-item></el-menu></el-aside><el-container><el-header><div style="display:flex;justify-content:space-between;align-items:center"><span>{{ $route.meta.title || '商家后台' }}</span><el-dropdown @command="handleCommand"><span style="cursor:pointer">{{ userInfo.nickname || '商家' }} <el-icon><ArrowDown/></el-icon></span><template #dropdown><el-dropdown-menu><el-dropdown-item command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></el-header><el-main><router-view/></el-main></el-container></el-container></template><script setup>import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';const router=useRouter();const userInfo=ref({});const handleCommand=(cmd)=>{if(cmd==='logout'){localStorage.removeItem('tllos_merchant_token');ElMessage.success('已退出');router.push('/login')}};onMounted(()=>{const info=localStorage.getItem('tllos_merchant_user');if(info)userInfo.value=JSON.parse(info)})</script><style scoped>.merchant-layout{height:100vh}.logo{height:60px;display:flex;align-items:center;justify-content:center;background:#002140}.logo h3{color:#fff;margin:0;font-size:16px}el-header{background:#fff;border-bottom:1px solid #e6e6e6;display:flex;align-items:center}el-main{background:#f0f2f5;padding:20px}</style>
